-- Run only as the migration owner, never as the API request role.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS vector;
CREATE DOMAIN evm_address AS text CHECK (VALUE ~ '^0x[0-9a-f]{40}$');
CREATE DOMAIN hash32 AS bytea CHECK (octet_length(VALUE) = 32);
CREATE DOMAIN uint256_num AS numeric(78,0) CHECK (VALUE >= 0 AND VALUE < power(2::numeric,256));
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), external_subject text UNIQUE NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), disabled_at timestamptz);
CREATE TABLE tenants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 120), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships (tenant_id uuid NOT NULL REFERENCES tenants, user_id uuid NOT NULL REFERENCES users, role text NOT NULL CHECK(role IN ('owner','admin','member')), revoked_at timestamptz, PRIMARY KEY(tenant_id,user_id));
CREATE TABLE wallet_bindings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users, address evm_address NOT NULL UNIQUE, verified_at timestamptz NOT NULL, revoked_at timestamptz, UNIQUE(id,user_id));
CREATE TABLE auth_challenges (nonce_hash hash32 PRIMARY KEY, expected_address evm_address NOT NULL, domain text NOT NULL, uri text NOT NULL, chain_id bigint NOT NULL, message_sha256 hash32 NOT NULL, expires_at timestamptz NOT NULL, consumed_at timestamptz);
CREATE TABLE auth_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users, tenant_id uuid NOT NULL REFERENCES tenants, token_hash hash32 UNIQUE NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz);
CREATE TABLE projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, name text NOT NULL CHECK(length(name) BETWEEN 1 AND 120), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,tenant_id));
CREATE TABLE project_acl (project_id uuid NOT NULL, tenant_id uuid NOT NULL, user_id uuid NOT NULL, permission text NOT NULL CHECK(permission IN ('read','write','admin')), PRIMARY KEY(project_id,user_id), FOREIGN KEY(project_id,tenant_id) REFERENCES projects(id,tenant_id), FOREIGN KEY(tenant_id,user_id) REFERENCES memberships(tenant_id,user_id));
CREATE TABLE api_keys (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, user_id uuid NOT NULL, name text NOT NULL, prefix text UNIQUE NOT NULL, token_hash hash32 UNIQUE NOT NULL, scopes text[] NOT NULL CHECK(cardinality(scopes)>0), project_ids uuid[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, revoked_at timestamptz, replaces_id uuid REFERENCES api_keys, last_used_at timestamptz, FOREIGN KEY(tenant_id,user_id) REFERENCES memberships(tenant_id,user_id));
CREATE TABLE key_envelopes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, kek_version text NOT NULL, wrapping_algorithm text NOT NULL CHECK(wrapping_algorithm='AES-256-GCM'), wrapped_dek bytea NOT NULL, wrapping_nonce bytea NOT NULL CHECK(octet_length(wrapping_nonce)=12), wrapping_tag bytea NOT NULL CHECK(octet_length(wrapping_tag)=16), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,tenant_id));
CREATE TABLE artifacts (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, key_envelope_id uuid NOT NULL,
 state text NOT NULL CHECK(state IN ('staged','uploading','uploaded','verified','indexed','failed','quarantined')),
 staging_ciphertext bytea, public_manifest jsonb NOT NULL, indexed_payload_sha256 hash32, crypto_version integer NOT NULL CHECK(crypto_version=1), cipher_sha256 hash32 NOT NULL, manifest_sha256 hash32 NOT NULL, plain_commitment hash32 NOT NULL,
 byte_size bigint NOT NULL CHECK(byte_size>0), sanitized_at timestamptz NOT NULL, reviewed_by uuid NOT NULL REFERENCES users, reviewed_at timestamptz NOT NULL, last_error text, created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(id,tenant_id), FOREIGN KEY(key_envelope_id,tenant_id) REFERENCES key_envelopes(id,tenant_id));
CREATE TABLE irys_transactions (
 tx_id text PRIMARY KEY CHECK(octet_length(tx_id) BETWEEN 1 AND 512), artifact_id uuid UNIQUE NOT NULL REFERENCES artifacts,
 network text NOT NULL, storage_product text NOT NULL, gateway_base_url text NOT NULL, receipt jsonb NOT NULL, uploaded_at timestamptz NOT NULL,
 manifest_tx_id text UNIQUE CHECK(octet_length(manifest_tx_id) BETWEEN 1 AND 512), manifest_receipt jsonb, verified_at timestamptz, permanence_verified boolean NOT NULL DEFAULT false,
 storage_verification_evidence jsonb, verified_cipher_sha256 hash32, verified_manifest_sha256 hash32,
 CHECK((verified_at IS NULL)=(verified_cipher_sha256 IS NULL)), CHECK((verified_at IS NULL)=(verified_manifest_sha256 IS NULL)), CHECK((manifest_tx_id IS NULL)=(manifest_receipt IS NULL)),
 CHECK(verified_at IS NULL OR (manifest_tx_id IS NOT NULL AND storage_verification_evidence IS NOT NULL)), CHECK(NOT permanence_verified OR (verified_at IS NOT NULL AND storage_product='permanent')));
CREATE TABLE approval_drafts (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, project_id uuid NOT NULL, requested_by uuid NOT NULL REFERENCES users, key_envelope_id uuid NOT NULL, content_ciphertext bytea NOT NULL, candidate_sha256 hash32 NOT NULL,
 state text NOT NULL CHECK(state IN ('scanned','egress_approved','distilling','distilled','approved','consumed','rejected','expired')),
 egress_approved_at timestamptz, approved_by uuid REFERENCES users, approved_at timestamptz, approval_token_hash hash32, approval_expires_at timestamptz, expires_at timestamptz NOT NULL, consumed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(id,tenant_id), FOREIGN KEY(project_id,tenant_id) REFERENCES projects(id,tenant_id), FOREIGN KEY(key_envelope_id,tenant_id) REFERENCES key_envelopes(id,tenant_id), CHECK((approval_token_hash IS NULL)=(approval_expires_at IS NULL)));
CREATE TABLE memories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, project_id uuid NOT NULL, created_by uuid NOT NULL REFERENCES users, created_at timestamptz NOT NULL DEFAULT now(), archived_at timestamptz, UNIQUE(id,tenant_id), FOREIGN KEY(project_id,tenant_id) REFERENCES projects(id,tenant_id));
CREATE TABLE memory_revisions (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), memory_id uuid NOT NULL, tenant_id uuid NOT NULL, revision integer NOT NULL CHECK(revision>0), artifact_id uuid NOT NULL, schema_version text NOT NULL CHECK(schema_version='1.0'), importance numeric(4,3) NOT NULL CHECK(importance BETWEEN 0 AND 1), valid_from timestamptz NOT NULL, valid_to timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(memory_id,revision), UNIQUE(id,tenant_id), FOREIGN KEY(memory_id,tenant_id) REFERENCES memories(id,tenant_id), FOREIGN KEY(artifact_id,tenant_id) REFERENCES artifacts(id,tenant_id), CHECK(valid_to IS NULL OR valid_to>valid_from));
CREATE TABLE capsules (root_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_tenant_id uuid NOT NULL REFERENCES tenants, creator_user_id uuid NOT NULL REFERENCES users, title text NOT NULL CHECK(length(title) BETWEEN 1 AND 160), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(root_id,owner_tenant_id));
CREATE TABLE capsule_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), root_id uuid NOT NULL, owner_tenant_id uuid NOT NULL, version bigint NOT NULL CHECK(version BETWEEN 1 AND 4294967295), artifact_id uuid NOT NULL, license_spdx_or_custom text NOT NULL, license_sha256 hash32 NOT NULL, review_state text NOT NULL CHECK(review_state IN ('pending','approved','rejected')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(root_id,version), UNIQUE(id,root_id), UNIQUE(id,owner_tenant_id), FOREIGN KEY(root_id,owner_tenant_id) REFERENCES capsules(root_id,owner_tenant_id), FOREIGN KEY(artifact_id,owner_tenant_id) REFERENCES artifacts(id,tenant_id));
CREATE TABLE capsule_previews (capsule_version_id uuid PRIMARY KEY, owner_tenant_id uuid NOT NULL, artifact_id uuid UNIQUE NOT NULL, safe_content jsonb NOT NULL CHECK(octet_length(safe_content::text)<=8192), safe_content_sha256 hash32 NOT NULL, reviewed_by uuid NOT NULL REFERENCES users, reviewed_at timestamptz NOT NULL, max_output_chars integer NOT NULL DEFAULT 1200 CHECK(max_output_chars BETWEEN 100 AND 2000), FOREIGN KEY(capsule_version_id,owner_tenant_id) REFERENCES capsule_versions(id,owner_tenant_id), FOREIGN KEY(artifact_id,owner_tenant_id) REFERENCES artifacts(id,tenant_id));
CREATE TABLE memory_chunks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, revision_id uuid NOT NULL, ordinal integer NOT NULL CHECK(ordinal>=0), locator text NOT NULL, sanitized_text text NOT NULL CHECK(length(sanitized_text) BETWEEN 1 AND 2000), embedding vector(1024) NOT NULL, embedding_model text NOT NULL CHECK(embedding_model='voyage-3.5-lite'), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(revision_id,ordinal), FOREIGN KEY(revision_id,tenant_id) REFERENCES memory_revisions(id,tenant_id));
CREATE TABLE capsule_chunks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_tenant_id uuid NOT NULL, capsule_version_id uuid NOT NULL, ordinal integer NOT NULL CHECK(ordinal>=0), locator text NOT NULL, sanitized_text text NOT NULL CHECK(length(sanitized_text) BETWEEN 1 AND 2000), embedding vector(1024) NOT NULL, embedding_model text NOT NULL CHECK(embedding_model='voyage-3.5-lite'), UNIQUE(capsule_version_id,ordinal), FOREIGN KEY(capsule_version_id,owner_tenant_id) REFERENCES capsule_versions(id,owner_tenant_id));
CREATE TABLE chain_deployments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), chain_id bigint NOT NULL, contract_address evm_address NOT NULL, deployment_block bigint NOT NULL, deployment_block_hash hash32 NOT NULL, code_hash hash32 NOT NULL, finalized_cursor bigint NOT NULL, UNIQUE(chain_id,contract_address));
CREATE TABLE capsule_root_bindings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), deployment_id uuid NOT NULL REFERENCES chain_deployments, capsule_root_id uuid NOT NULL REFERENCES capsules(root_id), initial_seller evm_address NOT NULL, onchain_root hash32 NOT NULL, UNIQUE(deployment_id,capsule_root_id), UNIQUE(deployment_id,onchain_root), UNIQUE(id,deployment_id));
CREATE TABLE listings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), deployment_id uuid NOT NULL REFERENCES chain_deployments, listing_id uint256_num NOT NULL, root_binding_id uuid NOT NULL, capsule_version_id uuid NOT NULL REFERENCES capsule_versions, seller evm_address NOT NULL, price_wei uint256_num NOT NULL CHECK(price_wei>0), fee_bps integer NOT NULL CHECK(fee_bps BETWEEN 0 AND 1000), fee_recipient evm_address NOT NULL, active boolean NOT NULL DEFAULT true, UNIQUE(deployment_id,listing_id), UNIQUE(id,deployment_id), FOREIGN KEY(root_binding_id,deployment_id) REFERENCES capsule_root_bindings(id,deployment_id));
CREATE TABLE chain_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), deployment_id uuid NOT NULL REFERENCES chain_deployments, tx_hash hash32 NOT NULL, log_index integer NOT NULL CHECK(log_index>=0), block_number bigint NOT NULL, block_hash hash32 NOT NULL, event_name text NOT NULL, decoded jsonb NOT NULL, state text NOT NULL CHECK(state IN ('observed','confirmed','orphaned')), observed_at timestamptz NOT NULL DEFAULT now(), UNIQUE(deployment_id,tx_hash,log_index), UNIQUE(id,deployment_id));
CREATE TABLE orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), deployment_id uuid NOT NULL, listing_row_id uuid NOT NULL, event_id uuid UNIQUE NOT NULL, buyer_wallet evm_address NOT NULL, buyer_user_id uuid REFERENCES users, paid_wei uint256_num NOT NULL, state text NOT NULL CHECK(state IN ('observed','confirmed','orphaned')), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(listing_row_id,deployment_id) REFERENCES listings(id,deployment_id), FOREIGN KEY(event_id,deployment_id) REFERENCES chain_events(id,deployment_id));
CREATE TABLE entitlements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid UNIQUE NOT NULL REFERENCES orders, user_id uuid NOT NULL REFERENCES users, capsule_version_id uuid NOT NULL REFERENCES capsule_versions, buyer_wallet evm_address NOT NULL, state text NOT NULL CHECK(state IN ('active','suspended')), last_chain_check_at timestamptz NOT NULL, UNIQUE(user_id,capsule_version_id,order_id));
CREATE TABLE project_capsules (tenant_id uuid NOT NULL, project_id uuid NOT NULL, user_id uuid NOT NULL REFERENCES users, entitlement_id uuid NOT NULL REFERENCES entitlements, capsule_version_id uuid NOT NULL REFERENCES capsule_versions, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(project_id,user_id,capsule_version_id), FOREIGN KEY(project_id,tenant_id) REFERENCES projects(id,tenant_id));
CREATE TABLE trial_counters (user_id uuid NOT NULL REFERENCES users, capsule_root_id uuid NOT NULL REFERENCES capsules(root_id), used_count integer NOT NULL DEFAULT 0 CHECK(used_count BETWEEN 0 AND 3), PRIMARY KEY(user_id,capsule_root_id));
CREATE TABLE trial_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, capsule_root_id uuid NOT NULL, capsule_version_id uuid NOT NULL, idempotency_key uuid NOT NULL, request_sha256 hash32 NOT NULL, state text NOT NULL CHECK(state IN ('reserved','running','succeeded','failed_charged','refunded')), response_ciphertext bytea, response_key_envelope_id uuid REFERENCES key_envelopes, lease_until timestamptz, lease_token uuid, delivered_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,capsule_root_id,idempotency_key), FOREIGN KEY(user_id,capsule_root_id) REFERENCES trial_counters(user_id,capsule_root_id), FOREIGN KEY(capsule_version_id,capsule_root_id) REFERENCES capsule_versions(id,root_id), CHECK((response_ciphertext IS NULL)=(response_key_envelope_id IS NULL)));
CREATE TABLE paid_query_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, project_id uuid NOT NULL, user_id uuid NOT NULL REFERENCES users, capsule_version_id uuid NOT NULL REFERENCES capsule_versions, idempotency_key uuid NOT NULL, request_sha256 hash32 NOT NULL, state text NOT NULL CHECK(state IN ('reserved','running','succeeded','failed')), response_ciphertext bytea, response_key_envelope_id uuid REFERENCES key_envelopes, lease_until timestamptz, lease_token uuid, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,capsule_version_id,idempotency_key), FOREIGN KEY(project_id,tenant_id) REFERENCES projects(id,tenant_id), CHECK((response_ciphertext IS NULL)=(response_key_envelope_id IS NULL)));
CREATE TABLE jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, requested_by uuid NOT NULL REFERENCES users, kind text NOT NULL CHECK(kind IN ('distill','upload','verify','index','sync_purchase','reconcile')), idempotency_key text NOT NULL, request_sha256 hash32 NOT NULL, payload jsonb NOT NULL, state text NOT NULL CHECK(state IN ('queued','running','retry','succeeded','failed')), result jsonb, attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0), run_after timestamptz NOT NULL DEFAULT now(), lease_until timestamptz, lease_token uuid, last_error text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,kind,idempotency_key));
CREATE TABLE outbox (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants, event_type text NOT NULL, aggregate_id uuid NOT NULL, payload jsonb NOT NULL, dedupe_key text UNIQUE NOT NULL, available_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz);
CREATE TABLE inference_budgets (budget_key text NOT NULL, day date NOT NULL DEFAULT current_date, used integer NOT NULL DEFAULT 0 CHECK(used>=0), PRIMARY KEY(budget_key,day));
CREATE TABLE chat_answers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, user_id uuid NOT NULL REFERENCES users, project_id uuid NOT NULL, answer_text text NOT NULL, abstained boolean NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(project_id,tenant_id) REFERENCES projects(id,tenant_id));
CREATE TABLE answer_citations (answer_id uuid NOT NULL REFERENCES chat_answers, ordinal integer NOT NULL, irys_tx_id text NOT NULL REFERENCES irys_transactions, artifact_id uuid NOT NULL REFERENCES artifacts, chunk_locator text NOT NULL, excerpt_sha256 hash32 NOT NULL, PRIMARY KEY(answer_id,ordinal));
CREATE INDEX memory_chunks_hnsw ON memory_chunks USING hnsw(embedding vector_cosine_ops);
CREATE INDEX capsule_chunks_hnsw ON capsule_chunks USING hnsw(embedding vector_cosine_ops);
CREATE INDEX memory_chunks_tenant ON memory_chunks(tenant_id,revision_id);
CREATE INDEX memory_project_time ON memories(tenant_id,project_id,created_at);
CREATE INDEX entitlement_access ON entitlements(user_id,capsule_version_id) WHERE state='active';
CREATE INDEX jobs_due ON jobs(run_after,created_at) WHERE state IN ('queued','retry','running');
CREATE INDEX outbox_due ON outbox(available_at) WHERE published_at IS NULL;
CREATE INDEX chain_blocks ON chain_events(deployment_id,block_number);
